'use strict';
(()=>{
 const C=FitableCore,$=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)],esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const STORE='fitable.movement.demo.v2',LEGACY='fitable.movement.demo.v1',UISTORE='fitable.movement.ui.v2',MALL='https://fitablekorea.com',today=C.dateKey,uid=()=>globalThis.crypto?.randomUUID?.()||'id-'+Date.now()+'-'+Math.random().toString(36).slice(2);
 const products=[{id:'OPB01',name:'오브제 와이드 풀업바',url:MALL+'/product/detail.html?product_no=126'},{id:'STM02',name:'스텝메이트 프로+',url:MALL+'/product/detail.html?product_no=100'}];
 const S={mode:'guest',tab:'today',session:{authenticated:false,auth_configured:false},demo:null,workouts:[],records:[],registrations:[],challenge:null,busy:false,error:'',storageOK:true,ui:{goal:'first_pullup',capability:'hang',exercise_id:'hang',assistance:'none',grip:'overhand',band_note:'',planned_sets:1,rest_seconds:0,target:'',performed_on:today(),active_id:null,timer:null,drafts:{},history:'all',muscle:'back'},pending:{},bootError:false};
 const active=()=>S.workouts.find(w=>w.status==='active'),ex=id=>C.exercises[id],product=id=>products.find(p=>p.id===id),owned=()=>S.registrations.some(r=>r.product_id==='OPB01'),isStatic=()=>location.hostname.endsWith('.github.io')||location.protocol==='file:';
 let toastTimeout;function notify(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').hidden=true,5000);}
 function warnStorage(){S.storageOK=false;$('#storage-warning').hidden=false;$('#storage-warning').textContent=S.mode==='real'?'이 브라우저에 타이머·입력 중인 값을 보관하지 못했어요. 서버에 저장한 세트는 유지되지만 새로고침하면 진행 중 입력·타이머는 복원되지 않을 수 있어요.':'브라우저에 저장하지 못했어요. 체험 기록과 타이머는 이 화면에서만 유지될 수 있어요. 새로고침 전에 내 기록을 내려받아 주세요.';}
 function persistUI(){try{if(S.mode==='demo')localStorage.setItem(UISTORE,JSON.stringify(S.ui));else if(S.mode==='real'&&active())sessionStorage.setItem('fitable.workout.ui.'+active().id,JSON.stringify({timer:S.ui.timer,drafts:S.ui.drafts,target:S.ui.target,active_id:S.ui.active_id,edit_position:S.ui.edit_position}));}catch{warnStorage();}}
 function updateDemo(mutate){try{const result=C.commitLocalChange(S.demo,mutate,serialized=>localStorage.setItem(STORE,serialized));S.demo=result.state;S.workouts=S.demo.workouts.slice().reverse().sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)));S.records=S.demo.records;S.registrations=S.demo.registrations;S.challenge=S.demo.challenge;S.storageOK=true;$('#storage-warning').hidden=true;return result.value;}catch{warnStorage();$('#storage-warning').textContent='브라우저에 저장하지 못했어요. 이번 변경은 적용하지 않았고 기존 기록과 진행을 유지했어요. 저장 공간을 확인한 뒤 다시 눌러 주세요.';throw new Error('저장하지 못했어요. 이번 변경을 적용하지 않고 기존 기록과 진행을 유지했어요. 저장 공간을 확인한 뒤 다시 눌러 주세요.');}}
 async function api(path,options={}){let response;try{response=await fetch(path,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});}catch{throw new Error('연결이 끊겼어요. 입력은 이 화면에 남아 있어요. 연결 후 다시 눌러 주세요.');}const data=await response.json().catch(()=>({}));if(response.status===401){S.mode='guest';S.session.authenticated=false;S.workouts=[];S.records=[];S.registrations=[];S.ui.timer=null;S.ui.drafts={};render();throw new Error('회원 연결이 만료됐어요. 다시 연결한 뒤 저장된 운동을 이어갈 수 있어요.');}if(!response.ok){const messages={active_workout_exists:'진행 중인 운동이 있어요. 오늘 탭에서 이어가 주세요.',workout_not_active:'이미 종료한 운동이에요. 현재 기록을 다시 확인해 주세요.',empty_workout:'완료한 세트가 없어요. 시도한 내용만 남기려면 중간 종료를 선택해 주세요.',request_id_conflict:'같은 요청의 내용이 바뀌었어요. 현재 기록을 확인한 뒤 다시 저장해 주세요.',stale_request:'현재 기록이 변경됐어요. 세트 내용을 확인한 뒤 다시 눌러 주세요.',not_found:'해당 기록이 없어요. 새로고침 후 확인해 주세요.',product_not_registered:'먼저 내 와이드 풀업바를 등록해 주세요.',invalid_assistance:'운동과 보조 조건을 함께 확인해 주세요. 밴드는 밴드 보조 풀업에서만 사용할 수 있어요.',invalid_value:'시간·횟수를 확인해 주세요. 완료는 1 이상, 시도·건너뛰기는 0으로 저장해요.',daily_limit:'오늘 기록할 수 있는 한도에 도달했어요.',invalid_origin:'페이지 주소를 확인한 뒤 새로고침해 주세요.'};const error=new Error(messages[data.error]||data.message||'저장하지 못했어요. 입력을 확인하고 다시 눌러 주세요.');error.code=data.error;throw error;}return data;}
 async function refresh(){if(S.mode==='demo'){S.workouts=S.demo.workouts.slice().reverse().sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)));S.records=S.demo.records;S.registrations=S.demo.registrations;S.challenge=S.demo.challenge;return;}const [w,r,summary]=await Promise.all([api('/api/workouts?limit=100'),api('/api/registrations'),api('/api/summary')]);let all=w.workouts||[],page=w,guard=0;while(page.has_more){if(++guard>100||!Number.isInteger(page.next_offset))throw new Error('운동 기록 전체를 불러오지 못했어요. 통계를 표시하기 전에 다시 연결해 주세요.');page=await api('/api/workouts?limit=100&offset='+page.next_offset);all.push(...(page.workouts||[]));}if(w.active_workout&&!all.some(x=>x.id===w.active_workout.id))all.push(w.active_workout);S.workouts=[...new Map(all.map(x=>[x.id,x])).values()];S.registrations=r.registrations||[];S.records=summary.records||[];S.challenge=summary.challenge;}
 const req=(key,payload)=>{const fingerprint=JSON.stringify(payload),old=S.pending[key];if(old?.fingerprint===fingerprint)return old.id;const id=uid();S.pending[key]={id,fingerprint};return id;};
 async function mutation(action){if(S.busy)return;S.busy=true;S.error='';const buttons=$$('button[type=submit]').map(el=>({el,text:el.textContent}));buttons.forEach(({el})=>{el.disabled=true;el.textContent='저장 중…';});try{await action();}catch(error){S.error=error.message;if(['stale_request','request_id_conflict','workout_not_active','active_workout_exists'].includes(error.code)){S.pending={};try{await refresh();}catch{}render();}else{const errorEl=$('#action-error');if(errorEl)errorEl.textContent=error.message;notify(error.message);}}finally{S.busy=false;buttons.forEach(({el,text})=>{if(el.isConnected){el.disabled=false;el.textContent=text;}});}}
 function illustration(){return '<svg viewBox="0 0 320 280" class="hero-art" fill="none" aria-hidden="true"><path d="M32 47h256M48 47v217m224-217v217" stroke="#b5c8b7" stroke-width="7" stroke-linecap="round"/><path d="M80 47h160" stroke="#f0efdf" stroke-width="12" stroke-linecap="round"/><path d="m128 106-22-27-5-31m63 60 24-28 9-32" stroke="#d8b396" stroke-width="12" stroke-linecap="round" stroke-linejoin="round"/><circle cx="147" cy="89" r="17" fill="#e0c0a7"/><path d="M130 83c-2-22 36-25 35 2l-16-12-19 10" fill="#202c45"/><path d="m128 111-8 66c22 9 37 8 55-1l-13-65c-12-5-22-5-34 0" fill="#a9beac"/><path d="m134 178-9 39-16 39m51-78 10 42 17 34" stroke="#e3e2ce" stroke-width="17" stroke-linecap="round"/><path d="m101 259 18 1m61-2 19 2" stroke="#1c2942" stroke-width="9" stroke-linecap="round"/><ellipse cx="153" cy="269" rx="96" ry="5" fill="#202c45" opacity=".4"/></svg>';}
 function heading(title,eyebrow='MY MOVEMENT'){return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="date">${new Intl.DateTimeFormat('ko-KR',{month:'long',day:'numeric',weekday:'long'}).format(new Date())}</p></div><span class="pill">와이드 풀업바 프로그램</span></div>`;}
 function button(text,action,cls='primary',extra=''){return `<button type="button" class="button ${cls}" data-action="${action}" ${extra}>${text}</button>`;}
 function entry(){return `<section class="entry"><div class="hero"><div class="hero-copy"><p class="eyebrow">ONE SET. YOUR OWN PACE.</p><h1>첫 매달리기부터,<br>나의 첫 풀업까지.</h1><p>와이드 풀업바를 꺼낸 오늘.<br>지금 가능한 한 세트에서 시작해요.</p><span class="pill">내 기구 · 내 페이스 · 내 기록</span></div>${illustration()}</div><div class="entry-steps"><div><span>01 / FIND YOUR START</span><h3>지금 가능한 동작부터</h3><p class="muted">아직 풀업이 어려워도 괜찮아요.<br>매달리기부터 직접 골라요.</p></div><div><span>02 / ONE SET AT A TIME</span><h3>한 세트씩, 바로 저장</h3><p class="muted">실제 초·횟수만 남기고<br>휴식 뒤 이어서 움직여요.</p></div><div><span>03 / YOUR OWN PROGRESS</span><h3>비교는 어제의 나와</h3><p class="muted">같은 동작과 보조 조건으로<br>처음·최근·최고를 살펴봐요.</p></div></div><div class="entry-actions"><h2>핏에이블 회원으로 시작하기</h2><p class="muted">구매처가 달라도 함께할 수 있어요.<br>내 기구와 운동 기록을 회원 계정에 모아요.</p><div class="button-row">${S.session.auth_configured?'<a class="button primary" href="/api/auth/start">자사몰 회원 연결하기 ↗</a>':`<a class="button primary" href="${MALL}/member/login.html" target="_blank" rel="noopener">자사몰 로그인 ↗</a>`}<a class="button" href="${MALL}/member/join.html" target="_blank" rel="noopener">회원가입 ↗</a></div><p class="small">${S.session.auth_configured?'자사몰 인증 화면에서 연결합니다.':'자사몰은 새 창에서 열려요. 회원 정보 자동 연결은 준비 중입니다.'}</p>${S.bootError?'<div class="floating-error">서버 연결을 확인하지 못했어요. 실제 회원의 저장 여부를 확인한 후 이용해 주세요.<button class="text-button" type="button" data-action="reload">다시 연결</button></div>':''}<div class="entry-demo"><p class="small">가입 전에 직접 둘러보세요. 체험 기록은 이 브라우저에만 저장되며 실제 보증 접수로 전달되지 않아요.</p>${button('가입 없이 체험하기 →','start-demo','soft full')}</div></div><p class="footer-note">FITABLE · MAKE MOVEMENT PART OF YOUR DAY</p></section>`;}
 function stats(){const m=C.metrics(S.workouts,S.records);return `<div class="stats"><div><span>이번 주 움직인 날</span><strong>${m.week_days}<small>일</small></strong></div><div><span>이어온 기록</span><strong>${m.streak}<small>일</small></strong></div><div><span>함께 움직인 날</span><strong>${m.total_days}<small>일</small></strong></div></div>`;}
 function setup(){const u=S.ui;return `<section class="card" id="setup-card"><div class="card-head"><div><p class="eyebrow">FIND YOUR START</p><h2>오늘의 한 세트 준비</h2></div><span class="pill">직접 설정</span></div><form id="setup-form"><div class="setup-section"><h3>어떤 목표로 시작할까요?</h3><div class="goal-grid">${Object.entries(C.goals).map(([id,g])=>`<button type="button" class="choice${u.goal===id?' selected':''}" data-goal="${id}" aria-pressed="${u.goal===id}"><strong>${g.name}</strong><span>${g.note}</span></button>`).join('')}</div></div><label class="field">지금 가능한 동작<select name="capability"><option value="hang"${u.capability==='hang'?' selected':''}>매달리기부터 시작하고 싶어요</option><option value="scapular_pull"${u.capability==='scapular_pull'?' selected':''}>견갑골 당기기를 할 수 있어요</option><option value="band_pullup"${u.capability==='band_pullup'?' selected':''}>호환 밴드로 보조 풀업이 가능해요</option><option value="pullup"${u.capability==='pullup'?' selected':''}>반동 없는 풀업이 가능해요</option></select><small>현재 가능한 동작으로 선택해요. 수준을 자동으로 판정하거나 진급시키지 않아요.</small></label><label class="field">오늘 기록할 운동<select name="exercise_id">${Object.values(C.exercises).map(e=>`<option value="${e.id}"${u.exercise_id===e.id?' selected':''}>${e.name}</option>`).join('')}</select></label><div class="inline-fields"><label class="field">그립<select name="grip"><option value="overhand"${u.grip==='overhand'?' selected':''}>손등이 나를 향하게</option><option value="underhand"${u.grip==='underhand'?' selected':''}>손바닥이 나를 향하게</option></select></label><label class="field">보조 조건<select name="assistance"><option value="none"${u.assistance==='none'?' selected':''}>보조 없음</option><option value="feet"${u.assistance==='feet'?' selected':''}>발 보조</option><option value="band"${u.assistance==='band'?' selected':''}>밴드 보조</option></select></label></div><label class="field" id="band-note-field"${u.assistance==='band'?'':' hidden'}>밴드 구분<input name="band_note" maxlength="120" value="${esc(u.band_note)}" placeholder="예: 내 초록 밴드 · 같은 부착 위치"${u.assistance==='band'?' required':''}><small>밴드 색·종류·부착 조건을 같게 적어야 같은 기록으로 비교할 수 있어요. 제품의 호환 조건을 먼저 확인해 주세요.</small></label><div class="inline-fields"><label class="field">계획할 세트<input name="planned_sets" type="number" min="1" max="10" step="1" inputmode="numeric" value="${u.planned_sets}" required><small>1~10세트 · 내가 정한 계획</small></label><label class="field">세트 사이 휴식<select name="rest_seconds">${[0,30,60,90,120,180,300,600].map(n=>`<option value="${n}"${u.rest_seconds===n?' selected':''}>${n===0?'타이머 사용 안 함':n<60?n+'초':(n/60)+'분'}</option>`).join('')}</select></label></div><div class="inline-fields"><label class="field">한 세트 목표 <span class="mini-label">선택</span><input name="target" type="number" min="1" max="${ex(u.exercise_id).max}" step="1" inputmode="numeric" value="${esc(u.target)}" placeholder="직접 정한 ${ex(u.exercise_id).unit}"><small>실제 수행값과 구분하는 참고 목표예요.</small></label><label class="field">운동한 날<input name="performed_on" type="date" min="2000-01-01" max="${today()}" value="${esc(u.performed_on)}" required></label></div><p id="action-error" class="form-error" role="alert">${esc(S.error)}</p>${owned()?'<button class="button primary full" type="submit">내 페이스로 시작하기 →</button>':button('먼저 와이드 풀업바 등록하기 →','register','primary full')}<p class="small program-note">세트 수·목표·휴식은 직접 정하는 값이에요. 몸 상태와 제품 사용 조건을 먼저 확인하고 무리하지 마세요.</p></form></section>`;}
 function challenge(){const m=C.metrics(S.workouts,S.records),start=S.challenge?.started_at?.slice(0,10);return `<section class="card"><p class="eyebrow">A LITTLE, EVERY DAY</p><h2>30일, 움직임의 흔적</h2><p class="muted section-gap">운동한 날을 하나씩 채워요.<br>쉬는 날도 나의 페이스예요.</p><div class="calendar" aria-label="30일 운동 기록">${Array.from({length:30},(_,i)=>{const key=start?C.shiftDate(start,i):null;return `<span class="${key&&m.dates.includes(key)?'done ':''}${key===today()?'now':''}" title="${key||'아직 시작하지 않음'}">${i+1}</span>`;}).join('')}</div>${start?`<p class="small">${esc(start)} 시작 · ${m.dates.filter(d=>d>=start&&d<=C.shiftDate(start,29)).length}일 기록<br>양수로 완료한 세트와 기존 간편 기록이 있는 날에 표시해요.</p>`:button('오늘부터 표시하기 →','challenge','soft full')}<p class="small section-gap">진도는 출석 기록이며 운동 강도·근육 성장 측정값이 아니에요.</p></section>`;}
 function renderToday(){const w=active();if(w&&S.ui.active_id===w.id)return renderSession(w);return `${heading('오늘, 나의 한 세트.','TODAY’S MOVEMENT')}${w?`<section class="card continue-card"><div class="card-head"><h2>멈췄던 곳에서 이어가요.</h2><span class="resume-tag">진행 중</span></div><p class="muted">${ex(w.exercise_id).name} · ${(w.sets||[]).length} / ${w.planned_sets}세트 처리<br>${esc(C.conditionLabel(w))}</p><div class="section-gap">${button('운동 이어가기 →','resume','primary full')}</div></section>`:`<section class="hero"><div class="hero-copy"><p class="eyebrow">WIDE PULL-UP BAR / OPB01</p><h2>가능한 만큼.<br>한 세트씩 쌓아요.</h2><p>처음이라면 매달리기부터.<br>작은 시작도 내 기록이 됩니다.</p>${button(owned()?'오늘 운동 준비하기 ↓':'내 기구 등록하고 시작하기 →',owned()?'scroll-setup':'register')}</div>${illustration()}</section>`}${stats()}${w?'':`<div class="grid"><div>${setup()}</div><div>${challenge()}</div></div>`}${w?challenge():''}<p class="footer-note">ONE SET. YOUR OWN PACE.</p>`;}
 function nextPosition(w){for(let i=1;i<=w.planned_sets;i++)if(!w.sets.some(s=>s.position===i))return i;return null;}
 function samePrevious(w,pos){return S.workouts.filter(x=>x.id!==w.id&&C.condition(x)===C.condition(w)).sort((a,b)=>String(b.performed_on).localeCompare(String(a.performed_on))||String(b.created_at).localeCompare(String(a.created_at))).flatMap(x=>x.sets.filter(C.positive).filter(s=>s.position===pos).map(s=>({...s,date:x.performed_on})))[0];}
 function timerMarkup(w,position){const t=S.ui.timer,e=ex(w.exercise_id);if(t&&t.workout_id===w.id&&!C.timerMatches(t,w.id,position)){return `<div class="notice"><strong>${Number(t.position)}세트 ${t.kind==='rest'?'휴식':'측정'}${t.running?'이 진행 중이에요.':'을 보관하고 있어요.'}</strong><br>다른 세트를 수정해도 원래 타이머는 유지돼요.<br><button type="button" class="text-button" data-return-timer="${Number(t.position)}">${Number(t.position)}세트로 돌아가기 →</button></div>`;}return `${t?.workout_id===w.id&&t.kind==='rest'?`<div class="timer-panel rest-panel"><div class="timer-title"><strong>세트 사이 휴식</strong><span class="small">마치면 내 페이스로</span></div><output class="timer-output" id="rest-output">${formatTime(C.timerValue(t))}</output><div class="timer-buttons">${button('30초 더','rest-add','soft')}${button('휴식 끝내기','rest-skip','')}</div></div>`:''}${e.id==='hang'?`<div class="timer-panel"><div class="timer-title"><strong>매달리기 스톱워치</strong><span class="small">실제 시간은 확인 후 저장</span></div><output class="timer-output" id="hang-output">${formatTime(t?.kind==='hang'&&t.workout_id===w.id?C.timerValue(t):0)}</output><div class="timer-buttons">${button(t?.kind==='hang'&&t.running?'일시정지':'측정 시작','hang-toggle','soft')}${button('초기화','hang-reset','')}${button('기록칸에 적용','hang-apply','')}</div><p class="small">타이머가 지나도 세트가 자동 완료되지는 않아요.</p></div>`:''}`;}
 function renderSession(w){const e=ex(w.exercise_id),position=S.ui.edit_position||nextPosition(w),saved=w.sets.find(s=>s.position===position),draft=S.ui.drafts[w.id+':'+position]??saved?.value??'',prev=samePrevious(w,position),count=w.sets.filter(C.positive).length;return `<div class="session-top"><div><p class="eyebrow">${esc(C.goals[w.goal]?.name||'MY SESSION')}</p><h1>${e.name}</h1><p class="session-condition">${esc(C.conditionLabel(w))}<br>${esc(w.performed_on)} · 계획 ${w.planned_sets}세트</p><p class="save-indicator${S.storageOK?'':' error'}">${S.mode==='demo'?(S.storageOK?'이 브라우저에 세트별로 저장해요.':'브라우저 저장 실패 · 이번 변경은 적용되지 않았어요.'):'회원 계정에 세트별로 저장해요.'}</p></div><button type="button" class="text-button" data-action="leave-session">잠시 나가기</button></div><div class="session-grid"><section class="card"><div class="set-track" aria-label="세트 진행">${Array.from({length:w.planned_sets},(_,i)=>{const s=w.sets.find(s=>s.position===i+1);return `<button type="button" class="set-chip${s?.status==='completed'?' done':s?' skipped':''}${position===i+1?' current':''}" data-position="${i+1}" aria-label="${i+1}세트 ${s?s.status==='completed'?'완료':s.status==='attempted'?'시도':'건너뜀':'미기록'}">${s?.status==='completed'?'✓':i+1}</button>`;}).join('')}</div>${position?`<form id="set-form"><p class="eyebrow">${position} / ${w.planned_sets} SET${saved?' · 수정 중':''}</p><h2>${saved?'실제 수행값을 수정해요.':'실제로 한 만큼만.'}</h2>${S.ui.target?`<div class="target">내가 정한 참고 목표 ${esc(S.ui.target)}${e.unit}</div>`:''}<div class="record-input"><input name="value" aria-label="실제 수행 ${e.unit}" type="number" min="0" max="${e.max}" step="1" inputmode="numeric" value="${esc(draft)}" placeholder="0" required><span>${e.unit}</span></div><p class="previous">${prev?`지난 같은 조건의 ${position}세트: <strong>${prev.value}${e.unit}</strong> · ${prev.date}`:'같은 조건의 지난 세트 기록이 아직 없어요.'}</p>${prev?`<div class="previous"><button type="button" class="text-button" data-action="use-previous" data-value="${prev.value}">지난 값 불러오기</button></div>`:''}${timerMarkup(w,position)}<div class="set-actions"><p id="action-error" class="form-error" role="alert">${esc(S.error)}</p><button type="submit" class="button primary full" data-busy>${saved?'수정한 세트 저장':'이 세트 완료하고 저장'} ✓</button><div class="secondary-actions"><button type="button" class="text-button" data-action="attempt">시도했지만 0${e.unit}</button><button type="button" class="text-button" data-action="skip">이 세트 건너뛰기</button></div>${saved?button('수정 취소','cancel-edit','soft full'):''}</div></form>`:`<div class="completed-message"><div class="empty-mark">✓</div><h2>계획한 세트를 모두 살펴봤어요.</h2><p class="muted section-gap">완료 ${count}세트 · 시도/건너뜀 ${w.sets.length-count}세트<br>아래 기록을 수정하거나 운동을 마칠 수 있어요.</p></div><p id="action-error" class="form-error" role="alert">${esc(S.error)}</p>`}<div class="divider"></div><div class="card-head"><h3>오늘의 세트</h3><span class="small">완료 ${count} / ${w.planned_sets}</span></div>${w.sets.length?w.sets.slice().sort((a,b)=>a.position-b.position).map(s=>`<div class="set-row"><span class="set-number">${s.position}</span><div class="record-info"><strong>${s.status==='completed'?`${s.value}${e.unit}`:s.status==='attempted'?`시도 · 0${e.unit}`:'건너뜀'}</strong><small>${s.effort?{easy:'쉬움',right:'적당',hard:'어려움'}[s.effort]+' · ':''}${s.discomfort?'불편함 기록':'저장됨'}</small></div><button type="button" class="text-button" data-edit-set="${s.position}">수정</button><button type="button" class="text-button" data-undo-set="${s.position}">취소</button></div>`).join(''):'<p class="small">아직 저장한 세트가 없어요. 첫 기록부터 시작해요.</p>'}<div class="section-gap button-row">${button('오늘 운동 마치기','finish','primary')}${button('중간 종료','stop','')}</div></section><div><section class="card"><div class="guide-header"><div><p class="eyebrow">BEFORE YOU MOVE</p><h2>동작 체크</h2></div><span class="pill">텍스트 가이드</span></div><svg class="guide-art" viewBox="0 0 300 125" aria-hidden="true"><path d="M55 20h190M70 20v85m160-85v85" fill="none" stroke="#8a9a89" stroke-width="4" stroke-linecap="round"/><circle cx="150" cy="48" r="9" fill="#2f3a56"/><path d="m137 63-15-19-6-24m47 43 15-19 6-24m-47 43-3 30m29-30 3 30m-29-28h26m-19 27-7 22m18-22 8 22" fill="none" stroke="#2f3a56" stroke-width="6" stroke-linecap="round"/></svg><ol class="guide">${e.guide.map(x=>`<li>${x}</li>`).join('')}</ol><p class="notice">설명서의 설치·허용 사용 조건을 먼저 확인하세요. 불편함이 느껴지면 멈추고 상태를 살펴보세요. 자체 동작 영상은 준비 중이에요.</p>${button('불편함이 있어 멈출게요','pain','danger full','data-gap="16"')}</section><section class="card"><p class="eyebrow">YOUR SETTINGS</p><h3>휴식 시간 바꾸기</h3><label class="field">다음 세트부터 적용<select id="session-rest">${[0,30,60,90,120,180,300,600].map(n=>`<option value="${n}"${w.rest_seconds===n?' selected':''}>${n===0?'사용 안 함':n+'초'}</option>`).join('')}</select></label><p class="small">운동 중 자리를 옮겨도 세트 기록은 유지돼요. 스톱워치·휴식은 ${S.mode==='demo'?'브라우저를 다시 열어도':'이 화면을 오가도'} 이어집니다.</p></section></div></div>`;}
 function history(){const groups=C.groups(S.workouts),filter=S.ui.history,list=S.workouts.filter(w=>filter==='all'||w.exercise_id===filter).slice().sort((a,b)=>b.performed_on.localeCompare(a.performed_on)||String(b.created_at).localeCompare(String(a.created_at)));return `${heading('쌓여가는 나의 기록.','YOUR OWN PROGRESS')}${stats()}<div class="history-filter"><button type="button" class="${filter==='all'?'selected':''}" data-filter="all">전체</button>${Object.values(C.exercises).map(e=>`<button type="button" class="${filter===e.id?'selected':''}" data-filter="${e.id}">${e.name}</button>`).join('')}</div>${groups.filter(g=>filter==='all'||g.workout.exercise_id===filter).map(g=>`<section class="card history-card"><p class="eyebrow">SAME CONDITIONS. YOUR PROGRESS.</p><h2>${ex(g.workout.exercise_id).name}</h2><p class="small">${esc(C.conditionLabel(g.workout))}</p><div class="metric-grid"><div><span>처음 완료</span><strong>${g.first}</strong><small>${ex(g.workout.exercise_id).unit}</small></div><div><span>최근 완료</span><strong>${g.latest}</strong><small>${ex(g.workout.exercise_id).unit}</small></div><div><span>한 세트 최고</span><strong>${g.best}</strong><small>${ex(g.workout.exercise_id).unit}</small></div></div>${chart(g)}<p class="small">같은 동작·그립·보조 조건의 양수 완료 세트만 비교해요. 운동한 날짜와 세트 최초 저장 순서로 정렬하며, 수정값은 원래 기록 위치에 반영해요.</p></section>`).join('')}<section class="card"><div class="card-head"><h2>운동 일지</h2><span class="small">${list.length}회</span></div>${list.length?list.map(w=>{const positive=w.sets.filter(C.positive),total=positive.reduce((a,s)=>a+s.value,0);return `<div class="session-row"><div class="session-row-header"><div><h3>${esc(ex(w.exercise_id)?.name||w.exercise_id)}</h3><p class="small">${w.performed_on} · ${w.status==='active'?'진행 중':w.status==='stopped'?'중간 종료':'운동 종료'}<br>${esc(C.conditionLabel(w))}</p></div><button type="button" class="text-button" data-delete-workout="${esc(w.id)}">삭제</button></div><div class="session-badges">${w.sets.length?w.sets.slice().sort((a,b)=>a.position-b.position).map(s=>`<span>${s.position}세트 ${s.status==='completed'?s.value+ex(w.exercise_id).unit:s.status==='attempted'?'시도 0':'건너뜀'}</span>`).join(''):'<span>저장한 세트 없음</span>'}</div><p class="small" data-gap="10">완료 ${positive.length}세트 · 세션 합계 ${total}${ex(w.exercise_id).unit}${w.discomfort?' · 불편함 기록':''}</p>${w.status==='active'?button('이어가기 →','resume','soft','data-gap="12"'):''}</div>`;}).join(''):'<div class="empty"><div class="empty-mark">＋</div><h3>첫 세트를 기다리고 있어요.</h3><p class="muted">오늘 탭에서 가능한 동작으로 시작해요.</p>'+button('오늘 운동 준비하기 →','go-today','soft')+'</div>'}</section>${S.records.length?`<section class="card"><p class="eyebrow">YOUR EARLIER JOURNAL</p><h2>기존 간편 기록</h2><p class="small section-gap">예전에 초·횟수만 남긴 기록이에요. 세트인지 총량인지 알 수 없어 새 세트 최고와 합치지 않아요.</p>${S.records.slice().reverse().map(r=>`<div class="set-row"><div class="record-info"><strong>${esc(ex(r.exercise_id)?.name||{step:'스텝 운동',squat:'맨몸 스쿼트'}[r.exercise_id]||r.exercise_id)}</strong><small>${esc(r.performed_on)} · 간편 기록</small></div><span class="set-value">${r.value}<small>${ex(r.exercise_id)?.unit||(r.exercise_id==='step'?'분':'회')}</small></span><button class="text-button" type="button" data-delete-legacy="${esc(r.id)}">삭제</button></div>`).join('')}</section>`:''}${bodyMap()}`;}
 function chart(group){const v=group.values.slice(-10),max=Math.max(1,...v.map(s=>s.value)),points=v.map((s,i)=>`${20+(v.length===1?130:i*260/(v.length-1))},${78-s.value/max*58}`).join(' ');return `<svg class="chart" viewBox="0 0 300 105" role="img" aria-label="최근 같은 조건 완료 세트 ${v.map(s=>s.value).join(', ')}${ex(group.workout.exercise_id).unit}"><path d="M20 80h260" stroke="#dfe4df"/><polyline points="${points}" fill="none" stroke="#6f9179" stroke-width="2.5"/>${v.map((s,i)=>`<circle cx="${20+(v.length===1?130:i*260/(v.length-1))}" cy="${78-s.value/max*58}" r="4" fill="#2f3a56"/>`).join('')}<text x="20" y="101">${v[0].date.slice(5).replace('-','.')}</text><text x="280" y="101" text-anchor="end">${v[v.length-1].date.slice(5).replace('-','.')}</text></svg>`;}
 function bodyMap(){const sets=C.completedSets(S.workouts).filter(s=>s.performed_on>=C.shiftDate(today(),-6)),names={back:'등',arms:'팔·전완',shoulders:'어깨'},counts=Object.fromEntries(Object.keys(names).map(m=>[m,sets.filter(s=>ex(s.workout.exercise_id)?.muscles.includes(m)).length])),selected=S.ui.muscle||'back';return `<section class="card"><p class="eyebrow">THE LAST 7 DAYS</p><h2>이번 주, 움직인 부위</h2><p class="small section-gap">${C.shiftDate(today(),-6)} ~ ${today()} · 부위를 눌러 근거 기록을 보세요.</p><div class="body-layout"><svg viewBox="0 0 140 240" class="body-map" role="img" aria-label="최근 7일 완료 세트가 연결된 부위"><circle cx="70" cy="24" r="17"/><path d="M48 48h44l9 68-19 19H58l-19-19z"/><path d="m57 133-9 93h19l4-78 4 78h20l-12-93z"/><path d="M44 56 26 93l-5 48 14 3 9-41 13-34m39-13 18 37 5 48-14 3-9-41-13-34" class="body-hit ${counts.arms?'active':''} ${selected==='arms'?'selected':''}" data-muscle="arms"/><path d="m49 51 21 7 21-7-4 60H53z" class="body-hit ${counts.back?'active':''} ${selected==='back'?'selected':''}" data-muscle="back"/><path d="m47 47-10 10 8 17 13-18m35-9 10 10-8 17-13-18" class="body-hit ${counts.shoulders?'active':''} ${selected==='shoulders'?'selected':''}" data-muscle="shoulders"/></svg><div>${Object.keys(names).map(m=>`<button type="button" class="muscle-button${selected===m?' selected':''}" data-muscle="${m}"><span>${names[m]}</span><span>${counts[m]} 완료 세트</span></button>`).join('')}</div></div><div class="body-details"><strong>${names[selected]}에 연결된 기록</strong><br>${sets.filter(s=>ex(s.workout.exercise_id)?.muscles.includes(selected)).length?Object.values(C.exercises).filter(e=>e.muscles.includes(selected)).map(e=>{const count=sets.filter(s=>s.workout.exercise_id===e.id).length;return count?`${e.name} · ${count}세트`:'';}).filter(Boolean).join('<br>'):'최근 7일 완료한 세트가 없어요.'}</div><p class="body-caption">동작과 연결한 부위별 세트 수예요. 한 세트가 여러 부위에 포함될 수 있어요. 근육 성장·회복률·운동 부족을 측정하는 그림이 아니에요.</p></section>`;}
 function program(){const goals=C.goals,m=C.metrics(S.workouts,S.records),pullup=S.workouts.some(w=>w.exercise_id==='pullup'&&w.assistance==='none'&&w.sets.some(C.positive));return `${heading('나에게 맞는 시작점.','YOUR STARTING POINT')}<section class="card"><p class="eyebrow">WIDE PULL-UP BAR</p><h2>세 가지 목표, 내 페이스로</h2><p class="muted section-gap">가능한 동작을 직접 골라 기록해요.<br>수행 기록을 확인한 뒤 다음 선택을 정해요.</p><div class="goal-grid section-gap">${Object.entries(goals).map(([id,g])=>`<button type="button" data-program-goal="${id}" class="choice${S.ui.goal===id?' selected':''}"><strong>${g.name}</strong><span>${g.note}</span></button>`).join('')}</div><div class="milestones"><div class="milestone${S.registrations.some(r=>r.product_id==='OPB01')?' done':''}"><strong>01 내 기구와 연결</strong>${owned()?'내 와이드 풀업바 등록됨':'기구를 등록하고 시작'}</div><div class="milestone${m.sets.length?' done':''}"><strong>02 첫 완료 세트</strong>${m.sets.length?'나의 첫 기록을 남겼어요':'양수로 완료한 첫 세트'}</div><div class="milestone${pullup?' done':''}"><strong>03 맨몸 풀업 기록</strong>${pullup?'보조 없는 풀업 기록 있음':'가능해질 때 직접 선택'}</div></div><p class="notice">이 표시는 실제 기록으로 확인한 개인 이정표예요. 시간·횟수만으로 다음 단계에 자동 진급시키지 않아요. 운동 목표와 구체적인 진급 기준은 검토 중입니다.</p></section><section class="card"><h2>동작을 알아봐요.</h2>${Object.values(C.exercises).map(e=>`<details><summary><strong>${e.name}</strong><span class="small">· ${e.unit}로 기록</span></summary><ol class="guide">${e.guide.map(x=>`<li>${x}</li>`).join('')}</ol><button type="button" class="button soft full" data-select-exercise="${e.id}">이 동작으로 준비하기 →</button></details>`).join('')}<p class="small section-gap">실제 설치 환경과 제품의 허용 사용 조건에 맞춰 선택하세요. 자세 영상은 준비 중이에요.</p></section>${bodyMap()}<section class="card"><p class="eyebrow">YOUR NEXT CHOICE</p><h2>다음에도, 같은 조건으로</h2><p class="muted section-gap">${C.groups(S.workouts).length?'최근 기록을 참고해 같은 동작을 다시 선택할 수 있어요. 쉬움·적당·어려움은 다음 선택을 위한 나만의 메모로 남아요.':'먼저 한 번 기록해 보세요. 그립과 보조 조건이 같을 때 처음·최근·최고를 비교할 수 있어요.'}</p><div class="section-gap">${button('오늘 운동 준비하기 →','go-today','primary full')}</div><div class="discovery"><h3>다른 움직임도 궁금하다면</h3><p class="small">내 기구 운동을 마친 뒤 천천히 살펴보세요.</p><a class="text-button" href="${products[1].url}" target="_blank" rel="noopener">스텝메이트 프로+ 알아보기 ↗</a></div></section>`;}
 function gear(){return `${heading('운동의 시작, 내 기구.','MY FITABLE')}<section class="card"><div class="card-head"><h2>나와 함께하는 기구</h2><button class="text-button" type="button" data-action="register">＋ 기구 등록</button></div>${S.registrations.length?S.registrations.map(r=>`<div class="gear-row"><div class="gear-icon">${esc(r.product_id)}</div><div class="record-info"><strong>${esc(product(r.product_id)?.name||r.product_id)}</strong><small>${esc(r.purchased_at||'')} · ${S.mode==='demo'?'체험 등록':'등록 요청'}</small></div><span class="pill">${r.status==='verified'?'구매 확인 완료':'구매 확인 대기'}</span></div>`).join(''):`<div class="empty"><div class="empty-mark">＋</div><h3>와이드 풀업바가 있나요?</h3><p class="muted">구매처가 달라도 등록할 수 있어요.<br>내 기구와 연결하고 운동을 시작해요.</p>${button('내 기구 등록하기 →','register','soft')}</div>`}<p class="notice">제품 등록 요청 후 구매 내역을 확인해요. 등록만으로 구매 인증·보증 연장이 완료되지는 않아요.${S.mode==='demo'?'<br>체험 등록은 실제 보증 접수가 아니에요.':''}</p></section><section class="card"><p class="eyebrow">YOUR EQUIPMENT. YOUR MOVEMENT.</p><h2>지금 기록할 수 있는 운동</h2><div class="gear-row"><div class="gear-icon">OPB01</div><div class="record-info"><strong>와이드 풀업바</strong><small>매달리기 · 견갑골 당기기 · 풀업 · 밴드 보조 풀업</small></div></div><p class="small section-gap">스텝메이트 등 다른 기구의 상세 운동은 준비 중이에요. 예전에 남긴 간편 기록은 내 기록에서 볼 수 있어요.</p></section>`;}
 function formatTime(seconds){return String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');}
 function render(){const entered=S.mode!=='guest';$('.bottom-nav').hidden=!entered;$('#account-button').textContent=S.mode==='demo'?'체험 계정':S.mode==='real'?'내 계정':'회원 연결';$('#mode-banner').hidden=S.mode!=='demo';$('#mode-banner').innerHTML='체험 중 · 기록은 이 브라우저에만 저장돼요.<button type="button" data-action="leave-demo">체험 종료</button>';$$('[data-tab]').forEach(b=>b.dataset.tab===S.tab?b.setAttribute('aria-current','page'):b.removeAttribute('aria-current'));$('#main').innerHTML=!entered?entry():S.tab==='history'?history():S.tab==='program'?program():S.tab==='gear'?gear():renderToday();bindForms();tick();}
 function tab(name){S.tab=name;persistUI();render();scrollTo({top:0,behavior:'auto'});$('#main').focus({preventScroll:true});}
 function readUI(){try{const v=JSON.parse(localStorage.getItem(UISTORE)||'null');if(v&&typeof v==='object'){for(const key of Object.keys(S.ui))if(key in v)S.ui[key]=v[key];if(!C.goals[S.ui.goal])S.ui.goal='first_pullup';if(!ex(S.ui.exercise_id))S.ui.exercise_id='hang';if(!S.ui.drafts||typeof S.ui.drafts!=='object')S.ui.drafts={};if(!['back','arms','shoulders'].includes(S.ui.muscle))S.ui.muscle='back';if(S.ui.timer&&!Number.isInteger(S.ui.timer.position))S.ui.timer=null;}}catch{}}
 function startDemo(){let saved;try{saved=JSON.parse(localStorage.getItem(STORE)||'null');if(!saved)saved=JSON.parse(localStorage.getItem(LEGACY)||'null');}catch{}S.demo=C.sanitize(saved);S.mode='demo';try{sessionStorage.setItem('fitable.demo.active','yes');}catch{}readUI();refresh().then(()=>{render();if(new URLSearchParams(location.search).has('product')&&!owned())openRegistration();});notify('체험을 시작했어요. 한 세트씩 직접 남겨보세요.');}
 function captureSetup(form){const d=new FormData(form);['capability','exercise_id','assistance','grip','band_note','target','performed_on'].forEach(k=>S.ui[k]=String(d.get(k)||''));['planned_sets','rest_seconds'].forEach(k=>S.ui[k]=Number(d.get(k)));persistUI();}
 function bindForms(){const setupForm=$('#setup-form');if(setupForm){setupForm.addEventListener('input',()=>captureSetup(setupForm));setupForm.addEventListener('change',e=>{captureSetup(setupForm);if(e.target.name==='capability'){S.ui.exercise_id=S.ui.capability;S.ui.assistance=S.ui.capability==='band_pullup'?'band':S.ui.assistance==='band'?'none':S.ui.assistance;persistUI();render();}else if(e.target.name==='exercise_id'||e.target.name==='assistance'){if(e.target.name==='exercise_id'){if(S.ui.exercise_id==='band_pullup')S.ui.assistance='band';else if(S.ui.assistance==='band')S.ui.assistance='none';}else{if(S.ui.assistance==='band')S.ui.exercise_id='band_pullup';else if(S.ui.exercise_id==='band_pullup')S.ui.exercise_id='pullup';}persistUI();render();}});setupForm.addEventListener('submit',event=>{event.preventDefault();captureSetup(setupForm);startWorkout();});}const setForm=$('#set-form');if(setForm){setForm.addEventListener('input',()=>{const w=active(),p=S.ui.edit_position||nextPosition(w);S.ui.drafts[w.id+':'+p]=$('[name=value]',setForm).value;persistUI();});setForm.addEventListener('submit',event=>{event.preventDefault();saveSet('completed');});}$('#session-rest')?.addEventListener('change',event=>{const seconds=Number(event.target.value);mutation(async()=>{const w=active();if(S.mode==='demo'){try{updateDemo(draft=>{draft.workouts.find(x=>x.id===w.id).rest_seconds=seconds;});}catch(error){event.target.value=String(w.rest_seconds);throw error;}}else{const r=await api(`/api/workouts/${encodeURIComponent(w.id)}`,{method:'PATCH',body:JSON.stringify({rest_seconds:seconds})});replaceWorkout(r.workout);}render();notify('다음 세트부터 휴식 설정을 적용해요.');});});}
 function replaceWorkout(w){if(!w)return;const index=S.workouts.findIndex(x=>x.id===w.id);if(index===-1)S.workouts.push(w);else S.workouts[index]=w;}
 function startWorkout(){mutation(async()=>{if(!owned()){openRegistration();return;}const u=S.ui;if(!Number.isInteger(u.planned_sets)||u.planned_sets<1||u.planned_sets>10)throw new Error('계획할 세트는 1~10 사이로 입력해 주세요.');if(u.assistance==='band'&&!u.band_note.trim())throw new Error('비교할 밴드 구분을 적어 주세요.');if(!C.validCondition(u.exercise_id,u.assistance))throw new Error('밴드 보조는 밴드 보조 풀업에서만 선택할 수 있어요. 동작과 보조 조건을 확인해 주세요.');const payload={goal:u.goal,exercise_id:u.exercise_id,assistance:u.assistance,grip:u.grip,band_note:u.assistance==='band'?u.band_note.trim():'',planned_sets:u.planned_sets,rest_seconds:u.rest_seconds,performed_on:u.performed_on},request_id=req('start',payload);let w;if(S.mode==='demo'){if(active())throw new Error('진행 중인 운동을 먼저 이어가거나 종료해 주세요.');w={...payload,id:request_id,status:'active',sets:[],created_at:new Date().toISOString(),finished_at:null};updateDemo(draft=>{draft.workouts.push(w);});}else w=(await api('/api/workouts',{method:'POST',body:JSON.stringify({...payload,request_id})})).workout;replaceWorkout(w);S.ui.active_id=w.id;S.ui.edit_position=null;S.ui.timer=null;delete S.pending.start;persistUI();render();scrollTo(0,0);});}
 function saveSet(status){mutation(async()=>{const w=active();if(!w)throw new Error('진행 중인 운동이 없어요.');const position=S.ui.edit_position||nextPosition(w);if(!position)throw new Error('저장할 세트를 선택해 주세요.');const raw=$('#set-form [name=value]')?.value,value=status==='completed'?Number(raw):0;if(status==='completed'&&(raw===''||!Number.isInteger(value)||value<1||value>ex(w.exercise_id).max))throw new Error(`완료한 실제 ${ex(w.exercise_id).unit}를 1~${ex(w.exercise_id).max} 사이 정수로 입력해 주세요. 0이면 시도 버튼을 눌러 주세요.`);const payload={value,status,effort:null,discomfort:false},key='set:'+w.id+':'+position,request_id=req(key,payload);if(S.mode==='demo'){const set={position,...payload,created_at:new Date().toISOString()};updateDemo(draft=>{const target=draft.workouts.find(x=>x.id===w.id),i=target.sets.findIndex(s=>s.position===position);const record=C.setRecord(i!==-1?target.sets[i]:null,set,new Date().toISOString());i===-1?target.sets.push(record):target.sets[i]=record;});}else replaceWorkout((await api(`/api/workouts/${encodeURIComponent(w.id)}/sets/${position}`,{method:'PUT',body:JSON.stringify({...payload,request_id})})).workout);delete S.pending[key];delete S.ui.drafts[w.id+':'+position];S.ui.edit_position=null;const current=active();S.ui.timer=S.ui.timer&&S.ui.timer.workout_id===w.id&&S.ui.timer.position!==position?S.ui.timer:status==='completed'&&current.rest_seconds>0&&nextPosition(current)?{workout_id:w.id,position:nextPosition(current),kind:'rest',running:true,deadline:Date.now()+current.rest_seconds*1000,remaining:current.rest_seconds*1000}:null;persistUI();render();notify(status==='completed'?(S.mode==='demo'&&!S.storageOK?'화면에는 기록했지만 브라우저에 저장하지 못했어요.':'세트가 저장됐어요.'):status==='attempted'?'0으로 시도한 내용을 남겼어요. 최고 기록에는 포함하지 않아요.':'이 세트를 건너뛰었어요.');});}
 function openModal(html){$('#modal-content').innerHTML=html;$('#modal').showModal();}
 function modalHead(title){return `<div class="modal-head"><div><p class="eyebrow">MY FITABLE</p><h2>${title}</h2></div><button type="button" class="icon-button" data-action="close-modal" aria-label="창 닫기">×</button></div>`;}
 function openRegistration(){const query=new URLSearchParams(location.search).get('product')||'OPB01';openModal(`${modalHead('내 기구 등록')}<p class="muted">${S.mode==='demo'?'체험에서는 예시 주문번호만 사용해요. 실제 개인정보는 입력하지 마세요.':'구매 내역에 표시된 정보를 입력해 주세요.'}</p><form id="registration-form"><label class="field">제품<select name="product_id" required>${products.map(p=>`<option value="${p.id}"${p.id===query?' selected':''}>${p.name}</option>`).join('')}</select></label><label class="field">구매처<select name="channel" required><option value="">선택해 주세요</option><option value="cafe24">핏에이블 자사몰</option><option value="naver">네이버 스마트스토어</option><option value="coupang">쿠팡</option><option value="other">기타 공식 판매처</option></select></label><label class="field">주문번호<input name="order_no" value="${S.mode==='demo'?'DEMO-EXAMPLE':''}" ${S.mode==='demo'?'readonly':''} minlength="3" maxlength="80" required autocomplete="off"></label><label class="field">구매일<input name="purchased_at" type="date" min="2000-01-01" max="${today()}" value="${today()}" required></label><p class="notice">등록 요청 상태에서도 내 기구로 운동 기록을 시작할 수 있어요. 구매 확인·보증 적용은 별도입니다.</p><p id="registration-error" class="form-error" role="alert"></p><button class="button primary full" type="submit">${S.mode==='demo'?'체험용 기구 등록':'제품 등록 요청'} →</button></form>`);$('#registration-form').addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.currentTarget);mutation(async()=>{const payload=Object.fromEntries(data);if(S.mode==='demo'){payload.order_no='DEMO-EXAMPLE';if(!S.demo.registrations.some(r=>r.product_id===payload.product_id)){updateDemo(draft=>{draft.registrations.push({...payload,id:uid(),status:'pending',channel:'demo'});});}}else await api('/api/registrations',{method:'POST',body:JSON.stringify(payload)});await refresh();$('#modal').close();S.tab='today';render();notify('내 기구와 연결했어요. 오늘의 운동을 준비해 보세요.');});});}
 function openFinish(status='completed',pain=false){const w=active();if(!w)return;const count=w.sets.filter(C.positive).length;openModal(`${modalHead(pain?'잠깐 멈추고 살펴봐요.':status==='stopped'?'한 만큼만 남길까요?':'오늘도 움직였어요.')}<div class="finish-summary"><strong>${count}</strong> 완료 세트<p class="small">${w.sets.filter(s=>s.status==='attempted').length}세트 시도 · ${w.sets.filter(s=>s.status==='skipped').length}세트 건너뜀<br>실제 수행한 기록만 유지해요.</p></div><form id="finish-form"><p class="muted">${pain?'불편함이 느껴지면 운동을 멈추고 상태를 확인해 주세요.':'오늘 느낌은 어땠나요? 선택하지 않고 마쳐도 괜찮아요.'}</p><div class="feedback">${['easy','right','hard'].map((e,i)=>`<button type="button" data-effort="${e}">${['쉬움','적당','어려움'][i]}</button>`).join('')}</div><input type="hidden" name="effort" value=""><label class="field"><input type="checkbox" name="discomfort" ${pain?'checked':''}>운동 중 불편함이 있었어요</label><p id="finish-error" class="form-error" role="alert"></p><button class="button primary full" type="submit">${status==='stopped'?'중간 종료하고 기록 유지':'오늘 운동 마치고 기록 유지'} →</button><button class="text-button full" type="button" data-action="close-modal">운동으로 돌아가기</button></form>`);$('#finish-form').addEventListener('submit',event=>{event.preventDefault();const form=event.currentTarget,data=new FormData(form),payload={status,effort:data.get('effort')||null,discomfort:data.has('discomfort')};mutation(async()=>{if(status==='completed'&&!count){$('#finish-error').textContent='완료 세트가 없어요. 시도 기록만 남기려면 중간 종료를 선택해 주세요.';return;}if(S.mode==='demo'){updateDemo(draft=>{Object.assign(draft.workouts.find(x=>x.id===w.id),payload,{finished_at:new Date().toISOString()});});}else replaceWorkout((await api(`/api/workouts/${encodeURIComponent(w.id)}/finish`,{method:'POST',body:JSON.stringify(payload)})).workout);S.ui.active_id=null;S.ui.timer=null;S.ui.edit_position=null;persistUI();$('#modal').close();S.tab='history';render();scrollTo(0,0);notify('운동을 마쳤어요. 실제 수행 기록을 확인해 보세요.');});});}
 function downloadDemo(){const blob=new Blob([JSON.stringify({mode:'demo',exported_at:new Date().toISOString(),...S.demo},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='fitable-demo-records.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function account(){if(S.mode==='guest'){$('.entry-actions')?.scrollIntoView({behavior:'smooth'});return;}openModal(`${modalHead(S.mode==='demo'?'체험 계정':'나의 계정')}<p class="muted">${S.mode==='demo'?'이 브라우저에만 저장하는 체험 기록이에요. 실제 자사몰 계정·제품 보증과 연결되지 않아요.':'자사몰 회원 계정과 연결되어 있어요. 기존 기록과 새 운동 세션을 함께 내려받을 수 있어요.'}</p><div class="section-gap">${S.mode==='demo'?button('체험 기록 내려받기','export-demo','soft full'):'<a class="button soft full" href="/api/export">내 기록 내려받기 ↗</a>'}</div><div class="section-gap">${button(S.mode==='demo'?'체험 종료':'로그아웃',S.mode==='demo'?'leave-demo':'logout','full')}${button(S.mode==='demo'?'체험 기록 초기화':'이 서비스의 내 정보 삭제',S.mode==='demo'?'clear-demo':'delete-account','danger full','data-gap="12"')}</div><p class="small section-gap">${S.mode==='demo'?'체험 종료 후에도 이 브라우저의 기록은 남아요. 초기화하면 삭제돼요.':'서비스 내 정보를 삭제해도 자사몰 회원은 유지됩니다.'}</p>`);}
 function tick(){const t=S.ui.timer;if(!t)return;const w=active();if(!w||t.workout_id!==w.id)return;const output=$(t.kind==='rest'?'#rest-output':'#hang-output');if(output)output.textContent=formatTime(C.timerValue(t));if(t.kind==='rest'&&C.timerValue(t)===0&&t.running){t.running=false;t.remaining=0;persistUI();const title=$('.rest-panel .timer-title strong');if(title)title.textContent='휴식 시간이 지났어요';}}
 setInterval(tick,250);
 document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')tick();else persistUI();});
 document.addEventListener('click',async event=>{const target=event.target.closest('button,[data-muscle]');if(!target)return;if(target.dataset.tab){tab(target.dataset.tab);return;}if(target.dataset.goal){S.ui.goal=target.dataset.goal;persistUI();render();$('#setup-card')?.scrollIntoView({block:'start'});return;}if(target.dataset.programGoal){S.ui.goal=target.dataset.programGoal;S.ui.exercise_id=C.goals[S.ui.goal].starter;S.ui.capability=S.ui.exercise_id;S.ui.assistance='none';tab('today');$('#setup-card')?.scrollIntoView({block:'start'});return;}if(target.dataset.selectExercise){S.ui.exercise_id=target.dataset.selectExercise;S.ui.capability=S.ui.exercise_id;S.ui.assistance=S.ui.exercise_id==='band_pullup'?'band':'none';tab('today');$('#setup-card')?.scrollIntoView({block:'start'});return;}if(target.dataset.filter){S.ui.history=target.dataset.filter;persistUI();render();return;}if(target.dataset.muscle){S.ui.muscle=target.dataset.muscle;const y=scrollY;persistUI();render();scrollTo(0,y);return;}if(target.dataset.effort){$$('[data-effort]',$('#modal')).forEach(b=>b.classList.toggle('selected',b===target));$('#finish-form [name=effort]').value=target.dataset.effort;return;}if(target.dataset.returnTimer){const t=S.ui.timer,w=active();if(t&&w&&t.workout_id===w.id){S.ui.edit_position=t.position;persistUI();render();}return;}if(target.dataset.position||target.dataset.editSet){S.ui.edit_position=Number(target.dataset.position||target.dataset.editSet);persistUI();render();return;}if(target.dataset.undoSet){mutation(async()=>{const w=active(),position=Number(target.dataset.undoSet);if(S.mode==='demo'){updateDemo(draft=>{const target=draft.workouts.find(x=>x.id===w.id);target.sets=target.sets.filter(s=>s.position!==position);});}else replaceWorkout((await api(`/api/workouts/${encodeURIComponent(w.id)}/sets/${position}`,{method:'DELETE'})).workout);S.ui.edit_position=null;if(C.timerMatches(S.ui.timer,w.id,position))S.ui.timer=null;S.pending={};persistUI();render();notify('세트 완료를 취소했어요. 다시 기록할 수 있어요.');});return;}if(target.dataset.deleteWorkout||target.dataset.deleteLegacy){if(target.dataset.confirm!=='yes'){target.dataset.confirm='yes';target.textContent='한 번 더 눌러 삭제';return;}mutation(async()=>{const id=target.dataset.deleteWorkout||target.dataset.deleteLegacy;if(S.mode==='demo'){updateDemo(draft=>{if(target.dataset.deleteWorkout)draft.workouts=draft.workouts.filter(w=>w.id!==id);else draft.records=draft.records.filter(r=>String(r.id)!==id);});}else await api('/api/'+(target.dataset.deleteWorkout?'workouts/':'records/')+encodeURIComponent(id),{method:'DELETE'});await refresh();if(S.ui.active_id===id){S.ui.active_id=null;S.ui.timer=null;}persistUI();render();notify('선택한 기록을 삭제했어요.');});return;}const action=target.dataset.action;if(!action)return;if(action==='start-demo')startDemo();if(action==='reload')location.reload();if(action==='close-modal')$('#modal').close();if(action==='register')openRegistration();if(action==='go-today')tab('today');if(action==='scroll-setup')$('#setup-card')?.scrollIntoView({behavior:'smooth'});if(action==='resume'){S.ui.active_id=active()?.id;S.ui.edit_position=null;tab('today');}if(action==='leave-session'){S.ui.active_id=null;persistUI();render();scrollTo(0,0);}if(action==='cancel-edit'){const w=active(),position=S.ui.edit_position;if(w&&position)delete S.ui.drafts[w.id+':'+position];S.ui.edit_position=null;persistUI();render();}if(action==='attempt')saveSet('attempted');if(action==='skip')saveSet('skipped');if(action==='use-previous'){const input=$('#set-form [name=value]');input.value=target.dataset.value;input.dispatchEvent(new Event('input',{bubbles:true}));input.focus();}if(action==='finish')openFinish('completed');if(action==='stop')openFinish('stopped');if(action==='pain')openFinish('stopped',true);if(action==='hang-toggle'){const w=active(),position=S.ui.edit_position||nextPosition(w),old=S.ui.timer;if(old&&!C.timerMatches(old,w.id,position)){notify('측정 중인 원래 세트로 돌아가 주세요.');return;}if(old?.kind==='rest'){S.ui.timer=null;}const t=S.ui.timer;if(t?.kind==='hang'&&t.workout_id===w.id){S.ui.timer=t.running?C.pauseTimer(t):{...t,running:true,started_at:Date.now()};}else S.ui.timer={workout_id:w.id,position,kind:'hang',running:true,started_at:Date.now(),elapsed:0};persistUI();render();}if(action==='hang-reset'){const w=active(),position=S.ui.edit_position||nextPosition(w);if(S.ui.timer&&!C.timerMatches(S.ui.timer,w.id,position)){notify('측정 중인 원래 세트로 돌아가 주세요.');return;}S.ui.timer=null;persistUI();render();}if(action==='hang-apply'){const t=S.ui.timer,w=active(),position=S.ui.edit_position||nextPosition(w);if(!C.timerMatches(t,w.id,position)){notify('이 세트에서 측정한 시간만 적용할 수 있어요. 원래 측정 중인 세트로 돌아가 주세요.');return;}if(t?.kind!=='hang'){notify('먼저 시간을 측정해 주세요.');return;}S.ui.timer=C.pauseTimer(t);const value=C.timerValue(S.ui.timer);if(value<1||value>3600){notify('1~3600초 사이의 실제 시간을 확인해 주세요.');return;}const input=$('#set-form [name=value]');input.value=value;input.dispatchEvent(new Event('input',{bubbles:true}));persistUI();render();notify('기록칸에 적용했어요. 완료 버튼을 눌러 저장해 주세요.');}if(action==='rest-add'){const t=S.ui.timer,w=active(),position=S.ui.edit_position||nextPosition(w);if(!C.timerMatches(t,w.id,position))return;if(t?.kind==='rest'){if(t.running)t.deadline+=30000;else{t.running=true;t.deadline=Date.now()+(t.remaining||0)+30000;}persistUI();tick();}}if(action==='rest-skip'){const w=active(),position=S.ui.edit_position||nextPosition(w);if(!C.timerMatches(S.ui.timer,w.id,position))return;S.ui.timer=null;persistUI();render();}if(action==='challenge')mutation(async()=>{if(S.mode==='demo'){updateDemo(draft=>{draft.challenge={started_at:today()};});}else await api('/api/challenge',{method:'POST',body:'{}'});await refresh();render();notify('오늘부터 30일 기록을 살펴볼게요.');});if(action==='export-demo')downloadDemo();if(action==='leave-demo'){$('#modal').close();S.mode='guest';try{sessionStorage.removeItem('fitable.demo.active');}catch{}S.demo=null;S.workouts=[];S.records=[];S.registrations=[];render();scrollTo(0,0);}if(action==='clear-demo'){if(target.dataset.confirm!=='yes'){target.dataset.confirm='yes';target.textContent='한 번 더 누르면 전체 초기화';return;}mutation(async()=>{updateDemo(draft=>{draft.workouts=[];draft.records=[];draft.registrations=[];draft.challenge=null;});S.ui.active_id=null;S.ui.timer=null;S.ui.drafts={};persistUI();await refresh();$('#modal').close();render();notify('체험 기록을 초기화했어요.');});}if(action==='logout')mutation(async()=>{await api('/api/auth/logout',{method:'POST',body:'{}'});S.mode='guest';S.session.authenticated=false;S.workouts=[];S.records=[];S.registrations=[];S.ui.timer=null;S.ui.drafts={};$('#modal').close();render();});if(action==='delete-account'){if(target.dataset.confirm!=='yes'){target.dataset.confirm='yes';target.textContent='한 번 더 누르면 등록·기록 전체 삭제';return;}mutation(async()=>{await api('/api/account',{method:'DELETE'});S.mode='guest';S.session.authenticated=false;S.workouts=[];S.records=[];S.registrations=[];S.ui.timer=null;S.ui.drafts={};$('#modal').close();render();notify('서비스 내 정보를 삭제했어요. 자사몰 회원은 유지돼요.');});}});
 $('#account-button').addEventListener('click',account);
 $('#modal').addEventListener('click',event=>{if(event.target!==$('#modal'))return;const rect=$('#modal').getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)$('#modal').close();});
 async function init(){if(isStatic()){let resume=false;try{resume=sessionStorage.getItem('fitable.demo.active')==='yes';}catch{}if(resume){startDemo();return;}render();return;}try{S.session=await api('/api/session');if(!S.session.authenticated){let resume=false;try{resume=sessionStorage.getItem('fitable.demo.active')==='yes';}catch{}if(resume){startDemo();return;}}if(S.session.authenticated){try{sessionStorage.removeItem('fitable.demo.active');}catch{}S.mode='real';await refresh();const w=active();if(w){S.ui.active_id=w.id;try{const cached=JSON.parse(sessionStorage.getItem('fitable.workout.ui.'+w.id)||'null');if(cached&&typeof cached==='object'){S.ui.timer=cached.timer?.workout_id===w.id&&Number.isInteger(cached.timer.position)?cached.timer:null;S.ui.drafts=cached.drafts&&typeof cached.drafts==='object'?cached.drafts:{};S.ui.target=cached.target||'';S.ui.edit_position=cached.edit_position||null;}}catch{}}}}catch{let resume=false;try{resume=sessionStorage.getItem('fitable.demo.active')==='yes';}catch{}if(resume){startDemo();notify('체험 기록을 복원했어요. 서버에 연결하지 않고 이 브라우저에서 이용해요.');return;}S.bootError=true;S.mode='guest';}render();if(S.mode==='real'&&new URLSearchParams(location.search).has('product')&&!owned())openRegistration();}init();
})();
